fn is_legacy_activity(diagram: &ActivityDiagram) -> bool {
    diagram.meta.source.as_deref().is_some_and(|source| {
        source.lines().any(|line| {
            let t = line.trim();
            t == "(*)"
                || t.starts_with("(*) ")
                || t.ends_with(" (*)")
                || (t.starts_with("===") && t.ends_with("===") && t.len() > 6)
        })
    })
}

