fn ellipse(&mut self, cx: f64, cy: f64, size: f64, filled: bool, stroke_w: f64) {
    let (acx, acy) = self.at(cx, cy);
    let r = size / 2.0;
    let fill = if filled { LINE_COLOR } else { "none" };
    let _ = write!(
        self.buf,
        r#"<ellipse cx="{}" cy="{}" fill="{fill}" rx="{}" ry="{}" style="stroke:{LINE_COLOR};stroke-width:{};"/>"#,
        n(acx),
        n(acy),
        n(r),
        n(r),
        n(stroke_w)
    )

    self.entries.push((normalized, id.clone()));
    id
}

/// Emit the `<filter>` elements (without the surrounding `<defs>` tag)
/// for every colour the registry has been asked about. Matches Java
/// PlantUML's element shape exactly: ordered `height`, `id`, `width`,
/// `x`, `y` attributes and the two filter children.
pub fn render_defs_content(&self) -> String {
    let mut out = String::new();
    use std::fmt::Write;
    for (color, id) in &self.entries {
        write!(
            &mut out,
            r#"<filter height="1" id="{id}" width="1" x="0" y="0"><feFlood flood-color="{color}" result="flood"/><feComposite in="SourceGraphic" in2="flood" operator="over"/></filter>"#,
        )

// ── Low-level emit helpers (PlantUML attribute conventions) ─────────────────────

fn escape_xml(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

fn fmt_n(v: f64) -> String {
    if v == v.floor() {
        format!("{}", v as i64)
    } else {
        fmt_coord(v)
    }
}

fn gantt_text(svg: &mut SvgBuilder, x: f64, y: f64, content: &str, font_size: f64, fill: &str) {
    let tl = text_width(content, font_size, false);
    let escaped = escape_xml(content);
    svg.raw_inline(&format!(
        r#"<text fill="{fill}" font-family="sans-serif" font-size="{fs}" lengthAdjust="spacing" textLength="{tl}" x="{x}" y="{y}">{escaped}</text>"#,
        fs = fmt_n(font_size),
        tl = fmt_coord(tl),
        x = fmt_coord(x),
        y = fmt_coord(y),
    )

/// Emit a `<text>` element in the Serif font (used by the Gantt
/// resource-load section). `textLength` is computed from the Serif metric
/// table.
fn gantt_text_serif(svg: &mut SvgBuilder, x: f64, y: f64, content: &str, font_size: f64) {
    gantt_text_serif_fill(svg, x, y, content, font_size, TEXT_COLOR);
}

fn gantt_text_serif_fill(
    svg: &mut SvgBuilder,
    x: f64,
    y: f64,
    content: &str,
    font_size: f64,
    fill: &str,
) {
    let tl = serif_text_width(content, font_size);
    let escaped = escape_xml(content);
    svg.raw_inline(&format!(
        r#"<text fill="{fill}" font-family="Serif" font-size="{fs}" lengthAdjust="spacing" textLength="{tl}" x="{x}" y="{y}">{escaped}</text>"#,
        fs = fmt_n(font_size),
        tl = fmt_coord(tl),
        x = fmt_coord(x),
        y = fmt_coord(y),
    )

    let tl = text_width(content, font_size, true);
    let escaped = escape_xml(content);
    svg.raw_inline(&format!(
        r#"<text fill="{TEXT_COLOR}" font-family="sans-serif" font-size="{fs}" font-weight="700" lengthAdjust="spacing" textLength="{tl}" x="{x}" y="{y}">{escaped}</text>"#,
        fs = fmt_n(font_size),
        tl = fmt_coord(tl),
        x = fmt_coord(x),
        y = fmt_coord(y),
    ));
}

