/// Open (non-closed) poly-line path drawn with a custom style (e.g. dashed).
fn open_path_dashed(&mut self, pts: &[(f64, f64)], style_attr: &str) {
    let mut d = String::new();
    for (i, (x, y)) in pts.iter().enumerate() {
        if i == 0 {
            d.push('M');
        } else {
            d.push_str(" L");
        }
        d.push_str(&fmt_coord(self.dx + *x));
        d.push(',');
        d.push_str(&fmt_coord(self.dy + *y));
    }
    self.svg.raw(&format!(
        r#"<path d="{d}" fill="none" style="{style_attr}"/>"#
    )

/// text baseline sits at `by + ascent`, the text starting at the box left edge.
/// Header/footer are 10pt #888888; caption is 12pt #000000.
fn emit_chrome_text(buf: &mut String, bx: f64, by: f64, r: &Ribbon) {
    let tl = pm::text_width(&r.text, r.font_size, false);
    let baseline = by + pm::ascent(r.font_size);
    let escaped = escape_text(&r.text);
    let fill = if r.font_size == CAPTION_FONT_SIZE {
        "#000000"
    } else {
        "#888888"
    };
    let fs = pm::fmt_coord(r.font_size);
    buf.push_str(&format!(
        r##"<text fill="{fill}" font-family="sans-serif" font-size="{fs}" lengthAdjust="spacing" textLength="{tl}" x="{x}" y="{y}">{escaped}</text>"##,
        tl = pm::fmt_coord(tl),
        x = pm::fmt_coord(bx),
        y = pm::fmt_coord(baseline),
    )

    display: String,
    bold: bool,
    italic: bool,
    underline: bool,
}

impl TextStyle {
    fn parse(content: &str) -> TextStyle {
        let bold = content.contains("<b>");
        let italic = content.contains("<i>");
        let underline = content.contains("<u>");
        TextStyle {
            display: strip_creole(content),
            bold,
            italic,
            underline,
        }
    }
}

