fn render_usecase_extremity(
    svg: &mut SvgBuilder,
    decoration: UseCaseExtremity,
    control: (f64, f64),
    endpoint: (f64, f64),
    color: &str,
    stroke_width: f64,
) {
    match decoration {
        UseCaseExtremity::Dependency => {
            let points = dependency_arrow_points(control, endpoint);
            svg.raw(&format!(
                r#"<polygon fill="{color}" points="{points}" style="stroke:{color};stroke-width:{stroke_width};"/>"#,
                stroke_width = fc(stroke_width),
            )

    stroke_width: f64,
) {
    match decoration {
        UseCaseExtremity::Dependency => {
            let points = dependency_arrow_points(control, endpoint);
            svg.raw(&format!(
                r#"<polygon fill="{color}" points="{points}" style="stroke:{color};stroke-width:{stroke_width};"/>"#,
                stroke_width = fc(stroke_width),
            ));
        }
        UseCaseExtremity::Extension => {
            let points = extension_arrow_points(control, endpoint);
            svg.raw(&format!(
                r#"<polygon fill="none" points="{points}" style="stroke:{color};stroke-width:{stroke_width};"/>"#,
                stroke_width = fc(stroke_width),
            )

    // PlantUML's drawLine normalises so the smaller x is x1.
    let (x1, x2) = if x1 <= x2 { (x1, x2) } else { (x2, x1) };
    write!(
        buf,
        r#"<line style="stroke:{STROKE};stroke-width:1.5;" x1="{x1}" x2="{x2}" y1="{y1}" y2="{y2}"/>"#,
        x1 = pm::fmt_coord(x1),
        x2 = pm::fmt_coord(x2),
        y1 = pm::fmt_coord(y1),
        y2 = pm::fmt_coord(y2),
    )
    .unwrap();
}

fn emit_box(buf: &mut String, x: f64, y: f64, node: &Itf) {
    if node.shape == WbsShape::Box {
        write!(
        buf,
        r#"<rect fill="{fill}" height="{h}" style="stroke:{STROKE};stroke-width:1.5;" width="{w}" x="{x}" y="{y}"/>"#,
        fill = node.fill,
        h = pm::fmt_coord(node.main_h),
        w = pm::fmt_coord(node.main_w),
        x = pm::fmt_coord(x),
        y = pm::fmt_coord(y),
    )
